INSERT INTO `Brands` VALUES ('1','Christian Dior','France','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-christian-dior.png','https://file.hstatic.net/1000340570/article/savage_274e526c589b4582a675c21fadd09542.png','Christian Dior là một nhà thiết kế đến từ Pháp, một thành viên của hội đồng Haute Couture bên cạnh Chanel, Maison Margiela, Givenchy hay Jean-Paul Gautier..., ấy là \"hội\" những nhà may ở đẳng cấp cao nhất, được thực hiện những bộ đồ may đo bằng tay với từng đối tượng khách hàng cụ thể và bằng những nguyên liệu tốt nhất. Christian Dior bước vào ngành thời trang với sự dìu dắt của huyền thoại Robert Piguet, và sau đó làm việc với Lucien Lelong và Pierre Balmain trước khi bắt đầu \"bán quần áo\" vào năm 1946. Sau đó 1 năm, Dior đã đem tới làng thời trang bộ sưu tập đầu tiên mang tên \"New Look\" và sử thi về Christian Dior chính thức bắt đầu. Dior ban đầu thiết kế nhiều các sản phẩm dành cho phái nữ, nhưng sau đó đã phủ sóng phạm vi hoạt động của mình sang cả nam giới với dòng đồ Dior Homme và Baby Dior dành cho trẻ em.\n\nDior tham gia ngành nước hoa khá sớm, dường như ngay lập tức và song song với việc phát triển ngành hàng quần áo của thương hiệu vào năm 1947, bằng Miss Dior, cái tên vẫn rất quen thuộc với người dùng nước hoa cho đến ngày nay. Mặc dù Dior qua đời chỉ sau 10 năm gây dựng thương hiệu, nhưng những người cộng sự của ông thật sự đã xây dựng bộ di sản của Christian Dior trở thành một đế chế. Parfums Dior, công ty được Dior lập ra phụ trách mảng hương thơm của nhãn hiệu đã tạo ra một bề dày huy hoàng cho cái tên Dior. Những cái tên như Diorissimo, Diorella hay Eau Savage của Edmond Rounitska đã làm dậy sóng toàn bộ làng hương thơm thế giới những năm 50, 60 của thế kỷ 20, đưa Dior lên một vị trí rất cao của ngành công nghiệp nước hoa. Giống như Chanel hay Hermès, Dior luôn đầu tư và duy trì cho mảng nước hoa của thương hiệu, với một (số) nghệ sĩ mùi hương hoạt động như \"in-house perfumer\" nhằm duy trì và phát triển tốt hơn DNA của mình. Đó là lý do mà cho đến ngày nay, Dior vẫn có chỗ đứng vô cùng vững chắc trong nền nước hoa hiện đại, bằng những dòng như Fahrenheit, Dior Homme, Sauvage, Eau Savage, Miss Dior, J\'adore, hay thậm chí có chỗ đứng ngang hàng với các nhà hương niche bằng bộ sưu tập La Collection Privée.','2025-12-30 16:05:32','2026-01-12 13:53:16',NULL),('10','Jo Malone','United Kingdom','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-jo-malone.png','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-jo-malone.jpg','Jo Malone mang phong cách Anh Quốc tinh tế với các mùi hương nhẹ nhàng, thanh khiết và dễ layer.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('11','Maison Francis Kurkdjian','France','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-maison-francis-kurkdjian.png','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-mfk.jpg','Maison Francis Kurkdjian nổi tiếng với những mùi hương niche tinh xảo, sang trọng và đầy nghệ thuật.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('12','Giorgio Armani','Italy','https://upload.wikimedia.org/wikipedia/commons/7/7a/Giorgio_Armani.svg','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-armani.jpg','Giorgio Armani mang phong cách Ý tinh tế, tối giản và sang trọng trong từng mùi hương.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('13','Lancôme','France','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-lancome.png','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-lancome.jpg','Lancôme là thương hiệu Pháp nổi tiếng với những dòng nước hoa nữ tính, quyến rũ và thanh lịch.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('14','Hermès','France','https://upload.wikimedia.org/wikipedia/en/e/e4/Herm%C3%A8s.svg','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-hermes.jpg','Hermès mang đến những mùi hương tinh tế, nghệ thuật và mang đậm dấu ấn thủ công Pháp.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('15','Bvlgari','Italy','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-bvlgari.png','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-bvlgari.jpg','Bvlgari kết hợp sự sang trọng Ý với phong cách táo bạo và hiện đại trong từng chai nước hoa.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('16','Prada','Italy','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-prada.png','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-prada.jpg','Prada mang đến những mùi hương độc đáo, hiện đại và mang tính nghệ thuật cao.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('17','Montblanc','Germany','https://upload.wikimedia.org/wikipedia/en/2/2c/Montblanc_Logo.svg','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-montblanc.jpg','Montblanc nổi tiếng với phong cách nam tính, lịch lãm và sang trọng.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('18','Valentino','Italy','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-valentino.png','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-valentino.jpg','Valentino mang đến những mùi hương lãng mạn, sang trọng và đậm chất Ý.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('19','Penhaligon’s','United Kingdom','https://upload.wikimedia.org/wikipedia/commons/0/0f/Penhaligon%27s_logo.svg','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-penhaligons.jpg','Penhaligon’s là thương hiệu nước hoa cổ điển Anh Quốc với phong cách hoàng gia và độc đáo.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('2','Chanel','France','https://upload.wikimedia.org/wikipedia/en/9/92/Chanel_logo_interlocking_cs.svg','https://theme.hstatic.net/1000340570/1000964732/14/brand-banner-chanel.jpg','Chanel là biểu tượng của sự thanh lịch và đẳng cấp, mang đến những mùi hương kinh điển vượt thời gian.','2025-12-30 16:05:32','2025-12-30 16:05:32',NULL),('20','Diptyque','France','https://theme.hstatic.net/1000340570/1000964732/14/logo-brand-di