--
-- Table structure for table `Products`
--

DROP TABLE IF EXISTS `Products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Products` (
  `id` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `brandId` varchar(255) DEFAULT NULL,
  `gender` enum('nam','nữ','unisex') NOT NULL DEFAULT 'unisex',
  `origin` varchar(255) DEFAULT NULL,
  `releaseYear` int DEFAULT NULL COMMENT 'Năm phát hành',
  `fragranceGroup` varchar(255) DEFAULT NULL COMMENT 'Nhóm hương chính, ví dụ: Gỗ đàn hương, Olibanum, Cam bergamot',
  `style` varchar(255) DEFAULT NULL COMMENT 'Phong cách: Lịch lãm, Nam tính, Lôi cuốn',
  `scentNotes` mediumtext COMMENT 'Hương đầu, giữa, cuối – có thể là JSON string hoặc text',
  `description` longtext,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `brandId` (`brandId`),
  CONSTRAINT `Products_ibfk_1` FOREIGN KEY (`brandId`) REFERENCES `Brands` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

