INSERT INTO `Products` VALUES ('06fb6c00-82df-4c42-baa3-131a9983198c','new2','30','nữ','Mỹ',2016,' Da lộn, Quả quýt hồng, Tiêu đen','Nữ tính, Tinh tế, Sang trọng','Hương đầu: Cam quýt, Tiêu đen; Hương giữa: Hoa hồng Bulgaria, Hoa hồng Grasse (Pháp), Hoa Violet, Hoa mộc lan; Hương cuối: Cỏ hương bài','aisja0q99 áoasasa','2026-01-17 03:59:59','2026-01-17 03:59:59',NULL),('07379dc3-3a87-4d9f-b74d-67ca3ee006ae','Yves Saint Laurent Y EDP','6','nam','Pháp',2018,'Táo xanh, Cây xô thơm, Amberwood, Gừng, Cam bergamot','Nam tính, Thu hút, Hấp dẫn','Hương đầu: Quả táo, Gừng, Cam Bergamot; Hương giữa: Xô thơm, Quả bách xù, Hoa phong lữ đỏ; Hương cuối: Nhựa hương, Đậu Tonka, Gỗ tuyết tùng, Cỏ hương bài, Nhựa hương Olibanum.','Yves Saint Laurent (YSL) Y Eau de Parfum có lẽ không còn xa lạ với các quý ông thân quen dùng nước hoa, đến mức cái tên này đã trở thành một đại diện cho hương thơm lịch lãm dành cho nam giới hiện đại. Bạn có biết tại sao lại như vậy không?<br>Lý do dễ hiểu nhất để Y Eau de Parfum thành công chinh phục các quý ông, ấy chính là ở mùi hương của chai nước hoa này. Đúng vậy, Y EDP sở hữu tất cả những nốt hương tuyệt vời dành cho nam giới, một chút trái cây giòn giã của Táo, nét đầm ấm thanh tao của Gừng, để dẫn vào cái tâm lõi Thảo mộc của mùi hương. Thảo mộc đã tạo nên sự nhã nhặn lịch lãm cho Y EDP, bằng mùi hương xanh xanh, hăng hăng, vừa lãnh đạm mà cũng đủ mạnh mẽ, bởi Xô thơm và một chút Bách xù, trên cái nền ngọt dịu và cứng chắc của Gỗ và Nhựa thơm. Y EDP có mọi thứ mà một người đàn ông cần ở hương thơm của mình, để phô diễn và tự tin với sự nam tính trời ban của mình.<br>Có thể nói, Y EDP là một hương thơm toàn diện để có thể trở thành “mùi hương đặc trưng” của bất kỳ quý ông nào, bởi sự dễ gần, dễ kiểm soát và có thể khoác lên mình bất cứ lúc nào ta muốn.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('077efdac-80bb-4d6b-a673-8a0501eec14f','new','7','nam','',NULL,'','','','','2026-01-15 14:29:23','2026-01-15 14:45:34','2026-01-15 14:45:34'),('08912c9c-0360-40e2-ae43-71279fd13a82','Penhaligon’s Cairo EDP','19','unisex','Anh',2019,'Vanilla, Hoa hồng','Quyến rũ, Tinh tế, Sang trọng','Hương đầu: Hoa hồng Đan Mạch, Nghệ Tây; Hương giữa: Vanilla, Tinh Dầu Hương Phụ – Cỏ Cú, Labdanum; Hương cuối: gỗ đàn hương, Quảng hoắc hương, tuyết tùng','Penhaligon’s Lothair được lấy cảm hứng từ một thành phố cổ kính, hay còn biết đến là thủ đô của Ai cập được lớp ánh sáng mặt trời phủ lên trông rất ấm áp. Cairo của Penhaligon’s có chứa Hoa hồng Damascan tinh tế, được ngâm trong vô số loại gỗ và gia vị. Một hương thơm trang trí đầy thủ công, tinh xảo và xa hoa vang vọng với nghệ tây và trầm hương, được cho là nước hoa của các vị thần, mùi hương kết thúc với hoắc hương và vani ở hương cuối để tạo cảm giác yên tâm quen thuộc như một buổi hoàng hôn từ đất nước của Thần Linh.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('0a201409-5b3f-4978-9a14-197e1ecc01c0','Giorgio Armani Code','12','nam','Pháp',2004,'Da thuộc, Hồi hương, Hoa olive, Đậu tonka','Nam tính, Ấm áp, Quyến rũ','Hương đầu: Cam Bergamot, Chanh; Hương giữa: Quả hồi, Hoa Olive, Gỗ Guaiac; Hương cuối: Da, Thuốc lá, Đậu Tonka','Armani Code của Giorgio Armani là một Eau de Toilette quyến rũ dành cho người đàn ông đương đại. Hương thơm hiện đại và tinh tế dành cho nam giới này cất lên như một ly cocktail tươi mát của mùi hương Bergamot và chanh. Tựa như vị rượu mạnh thấm vào trong huyết quản, cảm giác ở khoảnh khắc tiếp theo toả ra nhẹ nhàng và ấm áp bởi hương hoa Olive, quả Hồi và Gỗ Guaiac. Như thể diễn tả một cách chuẩn xác cách mà người đàn ông trưởng thành điềm nhiên thể hiện sự hấp dẫn của mình, hơi thuốc lá tản vào không gian, kéo theo đó là hương da và đậu Tonka làm ấm dần những cảm xúc và miêu tả triệt để sức hút từ anh chàng.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('0ddc02dc-560f-42b0-8456-0f4b2f1d11ae','Dior Sauvage Elixir EDP','1','nam','Pháp',2021,'Aromatic Spicy (tone cay ấm)','Nam tính, Hấp dẫn, Quyền lực','Hương đầu: Quế, Bạch Đậu Khấu, Nhục Đậu Khấu và Quả Bưởi; Hương giữa: Hoa Oải Hương; Hương cuối: Gỗ Đàn Hương, Cam Thảo, Hổ Phách, Cỏ Vetiver Haiti và Cây Hoắc Hương','Dior Sauvage Elixir EDP như một bản hòa âm đầy nam tính và lịch lãm. Những nốt hương đậm gia vị sẽ mang đến cho bạn sự ấn tượng rất khác của dòng nước hoa Dior Sauvage. Một mùi hương hoang dã hơn, ấm nồng hơn nhưng vẫn rất quyền lực và lôi cuốn.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('0e5586c4-7c1e-4df4-8d53-b5407a81af15','Gucci Bloom Eau de Parfum For Her','3','nữ','Anh, Đức, Pháp',2017,'Hoa huệ, Hoa nhài, Hoa kim ngân','Quyến rũ, Sang trọng, Quý phái','Hương đầu: Hoa nhài; Hương giữa: Hoa huệ; Hương cuối: Hoa sử quân tử','Gucci Bloom EDP For Her, một mùi hương tiêu biểu cho một nét đẹp thanh thoát và tao nhã chuẩn Ý. Nếu bạn lỡ say đắm mùi hương thanh lịch và quyến rũ của những đoá hoa trắng, thì nhất định bạn sẽ phải \'nghiêng mình ngả mũ\' khi bắt gặp mùi hương của Gucci Bloom EDP trên phố.<br>Chưng cất hương thơm của một vườn hoa nào Nhài và Huệ vào buổi sớm, Gucci Bloom EDP toả hương thơm nức lòng người, kiều diễm và tràn đầy sức sống. Ấy thế, đâu đó len lỏi trong từng tầng hương vẫn là chút vị đắng nhưng tươi, bạn có thể lấy mùi hương của Trà để tưởng tượng.<br>Từng phút từng giây trôi qua, ta chỉ ngày càng thêm yêu nét hương ý tứ, sang trọng mà Gucci Bloom EDP chưng cất. Nhiều người hỏi rằng Gucci Bloom EDP phù hợp với độ tuổi nào, mà quả thật thì tôi không biết chắc, vì với tôi, đây là một mùi hương không có tuổi và đẹp đẽ vô vàn.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('0e7c6ab0-3d0f-4113-a67b-55fa502ee630','Lancôme Trésor L\'Eau De Parfum','13','nữ','Pháp',1990,'Hương hoa cỏ phương đông','Quyến rũ, Nữ tính, Gợi cảm','Hương đầu: Quả dứa (quả thơm), Hoa tử đinh hương, Quả đào, Hoa mơ, Hoa linh lan thung lũng, Cam Bergamot, Hoa hồng; Hương giữa: Hoa diên vĩ, Hoa nhài, Hoa vòi voi, Hoa hồng; Hương cuối: Quả mơ, Gỗ đàn hương, Hổ phách, Xạ hương, Hương Vani, Quả đào','Hương thơm của nước hoa Lancôme Trésor đưa người ta vào một không gian đầy ma mị, mê mẩn tâm hồn bằng thứ hoa hồng dại, là lựa chọn chỉnh chu nhất cho người phụ nữ hiểu được giá trị thời gian.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('19677482-4a71-493b-8256-9403411f70ac','Jean Paul Gaultier Le Male','24','nam','Pháp, Tây Ban Nha',1995,'Vani, Hoa oải hương, Bạc hà, Quế, Đậu tonka','Sexy, Gợi cảm, Cuốn hút','Hương Đầu: Oải hương, Cam bergamot, Bạch đậu khấu, Bạc hà, Artemisia; Hương Giữa: Caraway, Hoa cam, Quế; Hương Cuối: Caraway, Hoa cam, Quế','Hiện đại, an yên và nhẹ nhàng là những gì ta có thể nhanh chóng thấy được trong Jean Paul Gaultier Le Male, kể cả là từ tông hương đầu tiên.<br>Dưới sự cộng hưởng đầy ăn nhập, Bạch đậu khấu và Bạc hà nhuốm lấy khứu giác hương thơm thanh cay, mềm mại, hòa quyện với Oải hương miên man cùng Cam bergamot. Không sôi nổi năng động, Le Male thể hiện bản chất lịch lãm, an toàn của mình bằng cách kết hợp mộc mạc giữa Hoa cam và Quế, nồng nàn và ấm áp khôn xiết.<br>Như một cái ôm siết ngày lạnh, Đàn hương, Vanilla cùng Tuyết tùng càng in đậm trong ta hình ảnh của một người tĩnh tại, thư thái cùng những khí chất không phải quý ông nào cũng may mắn có được.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('25ec24cb-f075-4870-9ff1-58b6b12b24e3','Jimmy Choo Urban Hero for Men','36','nam','Anh, Pháp',2019,'Da thuộc, Gỗ hồng, Cỏ hương bài','Tươi mới, Nam tính, Lịch lãm','Hương đầu: Tiêu đen, Chanh trứng cá; Hương giữa: Gỗ cẩm lai (Gỗ hồng), Cỏ hương bài; Hương cuối: Long diên hương, Da thuộc','Urban Hero là gương mặt mới được Jimmy Choo giới thiệu vào năm 2019, lấy cảm hứng từ sự phá cách, phong trần, có chút ngông nghênh nhưng lại cực kỳ nam tính, lôi cuốn sự chú ý của mọi người, và là tâm điểm của sức sống đang cuộn trào với cuộc sống đô thị bộn bề đang diễn ra. Jules Delet là gương mặt được Jimmy Choo chọn làm gương mặt đại diện cho hình ảnh của Urban Hero, một nghệ sĩ đường phố nổi tiếng, mang trong mình sự bí ẩn, tự tin cùng với sự nổi loạn một cách thông minh và tinh tế. Urban Hero được tạo ra từ những nguyên liệu cao cấp và quý hiếm, như Chanh trứng cá, một nguyên liệu đắt đỏ, và Gỗ cẩm lai, một loại gỗ quý. Urban Hero mang trong mình hương thơm nam tính đậm mùi da thuộc, mạnh mẽ, khoáng đạt và có sự phong lưu trong cách tỏa mùi. Urban Hero tựa như một làn khói trắng tỏa bay quanh một chiếc ghế da cao cấp được đóng bằng gỗ cẩm lai, nơi người đang ông đang phiêu theo từng nốt nhạc, sạch sẽ và kiệm lời trong ánh mắt, nhưng cuốn hút tuyệt đối bằng phong cách cá nhân đậm chữ \'tôi\' của chính bản thân.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('313b7a22-f1d4-4e11-bcb2-a5f33a309921','Tom Ford Ombré Leather','8','unisex','Mỹ',2018,'Hương da thuộc','Sang trọng, Ấm áp, Cổ điển','Hương Đầu: Bạch đậu khấu; Hương giữa: Hoa nhài Sambac, Da thuộc; Hương cuối: Cây hoắc hương, Hổ phách, Rêu sồi Moss','Nước hoa Tom Ford Ombré Leather không phải là một mùi hương dễ ngửi, nhưng càng ngửi thì bạn sẽ càng yêu thích. Mùi hương đâu đó là dư âm của sự cổ điển, tươi mát và cũng chính sự cá tính này đã tạo nên sự không giới hạn để cả chàng và nàng đều có thể thưởng thức.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('3558a49c-19e6-4ebc-a2a3-dc221663c14a','Jean Paul Gaultier Le Male Le Parfum','24','nam','Pháp, Tây Ban Nha',2020,'Nguyên liệu phương Đông, Hương vani, Hoa oải hương','Gợi cảm, Quyến rũ, Thu hút','Hương Đầu: Bạch Đậu Khấu; Hương Giữa: Hoa Oải Hương, Iris; Hương Cuối: Vani, Oriental note, Hương Gỗ.','Le Male Le Parfum của Jean Paul Gaultier là một hương thơm phương Đông dành cho nam giới. Được ra mắt vào năm 2020, Le Male Le Parfum được tạo ra bởi Quentin Bisch và Nathalie Gracia-Cetto.<br>Mở đầu bằng sự độc tôn của Bạch Đậu Khấu, Le Male Le Parfum thể hiện được sự độc đáo và táo bạo trong cách suy nghĩ và hành động của mình khi chỉ dùng 1 loại hương cho tầng hương đầu tiên nhằm thách thức cũng như lôi kéo sự tò mò của khán giả về phía mình.<br>Không ngần ngại tỏ sự thông minh, lôi cuốn của mình, Le Male Le Parfum thể hiện mình dưới một vỏ bọc hoàn hảo, sự ngọt ngào được trau chuốt cùng với sự phóng khoáng của Hoa Oải Hương và Iris, khiến Le Male trở thành tâm điểm của đám đông.<br>Không dừng lại ở đó, Le Male Le Parfum khiến người ta liên tưởng đến những cái ôm đầy ấm áp, an toàn của gã đàn ông lịch thiệp, một cái ốm mang ý nghĩa của sự lãng mạn đặc trưng mùi hương của những đêm lạnh phương Đông Huyền bí hòa cùng hương gỗ đang dai dẳng mùi hương nơi khứu giác.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('40e52ab8-966c-44f8-b118-12ced8f0acd4','Giorgio Armani Acqua di Gio EDP','12','nam','Pháp',2022,'Hương Biển, Khoáng Sản, Qủa Cam','Nam tính, Hiện đại, Phóng khoáng','Hương đầu: Hương Biển, Quýt xanh; Hương giữa: Xô thơm, Oải hương, Chi Mỏ hạc; Hương cuối: Hương Khoáng, Cỏ Hương bài, Hoắc hương','Mang trong mình hơi thở Thuỷ sinh, Giorgio Armani Acqua di Gio Eau de Parfum là vẻ đẹp của một người đàn ông cá tính, hiện đại và có đôi phần \'ướt át\'. Ra mắt từ năm 2022, ấn phẩm đươc sự đón nhận nồng nhiệt của giới mộ điệu, bởi đây không chỉ là một sự kế thừa và phát huy DNA của Acqua di Gio nguyên bản, mà còn là một phiên bản hoàn chỉnh của sự giao thoa giữa giữa bản gốc và bản Essenza.<br>Ấn phẩm là sự mô tả về một không gian rộng lớn và vô tận như đang đắm mình vào biển cả, không giới hạn, không chút áp lực và không có sự hạn chế. Hương thơm của Khoáng chất kết hợp cùng Quýt xanh, dịu ngọt nhưng cực tươi mát, lại càng nhấn mạnh vẻ đẹp của biển cả. Càng về sau, hương thơm càng nồng ấm, hoang dại của Xô thơm lẫn trong cái kết cấu phức tạp của Chi Mỏ hạc, tạo nên cái trầm lắng bên trong mỗi quý ông.<br>Để rồi người đàn ông ấy quyến luyến mọi cô gái bằng sự phóng khoáng, lơ đãng của mình. Thoảng hoặc theo đó chút Cỏ Hương bài, chút Hoắc hương nồng đượm hương Gỗ đặc trưng. Những nốt hương trong Giorgio Armani Acqua di Gio EDP đan xen tựa hệt cảm xúc biến chuyển của một gã trai hiện đại, và bên trong họ là những phần tâm hồn tươi tắn, phóng khoáng.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('42304e19-d60b-4655-99fe-6567efbb8032','new3','30','nữ','',NULL,'','','','','2026-01-17 04:01:38','2026-01-17 07:49:58','2026-01-17 07:49:58'),('452fa349-5bfa-4358-b6e5-238e4dfd5188','Prada L\'Homme Intense','16','nam','Pháp, Tây Ban Nha',2017,'Hoa diên vĩ, Đậu tonka, Da thuộc','Nam tính, Tự tin, Hiện đại, Cuốn hút','Hương đầu: Hoa Diên Vĩ; Hương giữa: Quảng Hoắc Hương, Hổ Phách; Hương cuối: Da Thuộc, Đậu Tonka, Gỗ Đàn Hương','Bộ đôi nước hoa mới của Prada, Prada La Femme và Prada L\'Homme, ra mắt thị trường vào giữa năm 2016. Một năm sau, các chế phẩm được cải tiến ở nồng độ Eau de Parfum Intense và đã mang lại những tiếng tăm vang dội trong giới mộ điệu mùi hương.<br>Prada L\'Homme Intense hứa hẹn \'một trải nghiệm nhiều tầng\' và cải tiến từ mùi hương của hoa diên vĩ kết hợp cùng hổ phách với bộ đôi hương da thuộc và hoắc hương, trong khi đậu tonka mang đến cho nó một dấu ấn phương Đông. Mục tiêu của mùi hương và dáng chai mờ đục là gợi lên \'bản chất khó nắm bắt của người đàn ông Prada đa diện\'.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('45e37af1-5b12-4499-b3a3-9d9d726d1b92','Valentino Uomo Born In Roma Green Stravaganza','18','nam','Pháp',2024,'Hương Cam Bergamot, Cà Phê, Cỏ Hương Bài','Tinh Tế, Nam Tính, Nhẹ Nhàng','Hương đầu: Cam Bergamot; Hương giữa: Cà phê; Hương cuối: Cỏ hương bài','Khi bản lĩnh được tỏa sáng giữa vườn xanh rực rỡ<br>Ra mắt vào năm 2024, Valentino Uomo Born in Roma Green Stravaganza là một chương mới đầy năng lượng trong bộ sưu tập Born in Roma. Lấy cảm hứng từ những khu vườn đậm chất Ý giữa lòng thành Rome, mùi hương là sự tôn vinh cá tính tự do, sôi nổi và bản lĩnh của người đàn ông hiện đại, luôn chọn sống khác biệt.<br>Ngay từ những nốt đầu tiên, Green Stravaganza mở ra với cam Bergamot vùng Calabria, tươi sáng, rạng rỡ như ánh nắng Địa Trung Hải. Khi lớp hương lắng lại, nốt cà phê dần hiện lên, với chút mạnh mẽ, gợi cảm và tràn đầy năng lượng, như nhịp sống sôi động của thành phố. Kết thúc của hương thơm là sự kết hợp tinh tế giữa Cỏ hương bài ấm khô nồng nàn đầy quyến rũ, để lại một dấu ấn vừa chín chắn vừa cá tính.<br>Đây là mùi hương dành cho những người đàn ông yêu thích sự bứt phá nhưng vẫn giữ vững bản sắc riêng. Phù hợp trong những buổi hẹn hò, tiệc tối hay bất kỳ khoảnh khắc nào bạn muốn tỏa sáng một cách lịch lãm, cuốn hút và đầy khác biệt.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('4690694e-8a1e-49f5-896d-4552663d4b9e','Hermes Terre D’Hermes EDT','14','nam','Pháp',2006,'Hương gỗ cay nồng','Nam tính, Chững chạc, Phong trần','Hương đầu: Quả cam, Quả bưởi; Hương giữa: Tiêu, Chi quỳ thiên trúc; Hương cuối: Cây hoắc hương, Gỗ tuyết tùng, Cỏ hương bài','Nếu những mùi hương “đương đại” xô bồ đã khiến bạn nhàm chán, hãy một lần tìm đến sự cổ điển, lịch lãm trong không gian mùi hương của Terre d’Hermes - cả một vùng trời đất rộng lớn kỳ diệu mà rồi chàng trai nào cũng sẽ đạt tới độ trưởng thành và bản lĩnh để thưởng thức một lần trong đời.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('4f999511-2f1a-46e8-b946-9025b7068844','Maison Francis Kurkdjian Oud','11','unisex','Pháp',2012,'Hương Hoa Nghệ Tây, Trầm Hương, Quảng Hoắc Hương','Tinh Tế, Hấp Dẫn, Thanh Lịch','Hương chính: Cây hoắc hương, Gỗ tuyết tùng, Nghệ tây, Gỗ trầm hương, Dấu trám','','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('5489f02b-dd36-4bb8-9e40-280217f3d388','Prada Luna Rossa Ocean','16','nam','Pháp',2021,'Hoa oải hương, Cam bergamot, Hoa diên vĩ','Nam tính, Tươi mát, Hấp dẫn','Hương đầu: Cam bergamot, Tiêu hồng, Ngải cứu; Hương giữa: Oải hương, Hoa diên vĩ, Xô thơm, Da lộn, Nhuỵ hoa nghệ tây; Hương cuối: Xạ hương, Cỏ hương bài, Hoắc hương, Caramel','Prada vẫn luôn được biết đến với phong cách làm hương tinh tế chuẩn mực, thể hiện rõ nét nam tính nhưng không hề đi theo \'lối mòn\' tác chế. Chính thế, những ấn phẩm hương thơm khoác tên Prada vẫn luôn giữ được sự yêu thích của người nghiện hương mặc cho sự bào mòn của thời gian và thời đại.<br>Đừng để cái tên Luna Rossa Ocean khiến bạn lầm tưởng rằng đây là mùi hương của nước, của biển. Dầu cho thực sự có một nét tính cách rất dễ chịu, nhưng Prada Luna Rossa Ocean lại được làm nên trước tiên bởi những nét hương của Cam chanh. Từ tông vị thanh chua ấy, Hoa diên vĩ và Xạ hương mới dần phủ lên một lớp phấn, bông bông mịn màng, làm dịu dàng đi tổng thể nhưng vẫn nam tính hiện đại bởi Xô thơm và Cỏ hương bài.<br>Oải hương là một nét hương sáng, nói thế không có nghĩa sự xuất hiện của loài hoa này sẽ giảm đi chiều sâu sắc của mùi hương, mà \'sáng\' ở đây tượng trưng cho hiệu ứng miên man, nồng đượm mà nó đã gíup tôn lên cho tổng thể. Tinh tế, phong cách, hiện đại, đó là những gì ta có thể tóm gọn về Prada Luna Rossa Ocean.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('5e1a92cf-63cd-4b74-be34-5ff1c0c1f61a','Louis Vuitton Imagination EDP','37','unisex','Pháp',2021,'Nhóm hương cam chanh thơm ngát','Sang trọng, Hiện đại','Hương đầu: quýt Yuzu, cam bergamot Calabria, Cam Sicilia; Hương giữa: Gừng Nigeria, Hoa cam của Tunisia, Quế Ceylon; Hương cuối: Trà đen Trung Quốc, Ambroxan, Olibanum, Gỗ Guaiac','Louis Vuitton Imagination là sự kết hợp hoàn hảo giữa tinh thần tự do, sáng tạo và phong cách sống hiện đại. Đây là một mùi hương dễ dùng, dễ yêu, và chắc chắn sẽ làm hài lòng những ai đang tìm kiếm một chai nước hoa mùa hè tinh tế nhưng không nhàm chán.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('5f1ff1f4-208a-45e7-b7a6-440f0d904d8b','Chanel Chance Eau Vive','2','nữ','Pháp',2015,'Cam đỏ, Bưởi , Hương cam chanh','Tươi mới, Thanh lịch, Tinh tế','Hương đầu: Quả cam đỏ, Quả bưởi, Các notes citrus; Hương giữa: Hoa nhài, Xạ hương trắng; Hương cuối: Cỏ hương bài, Gỗ tuyết tùng, Hoa diên vĩ','Chanel ra mắt Chance Eau Vive vào năm 2015, dưới bàn tay của Olivier Polge, một chiếc mũi tài năng của nhà Chanel và là con trai của Jacques Polge, một nhà pha chế nước hoa quen thuộc với các fan hâm mộ của nhà Chanel. Chance Eau Vive là một flanker nằm trong bộ sưu tập Chanel Chance của hãng, với những cái tên quen thuộc nổi tiếng như Chanel Chance (2003), Chanel Chance Eau Fraiche (2007) và Chanel Chance Eau Tendre (2010), với mục tiêu là những mùi hương tươi tắn dịu dàng và dành cho các quý cô trẻ trung.<br>Olivier Polge đã kết hợp note hương bưởi lấp lánh với hương cam đỏ mọng nước, tạo ra một sự bùng nổ với các note hương citrus và kết hợp chúng với sự thanh lịch của hoa nhài và xạ hương trắng quyến rũ. Ở phần cuối của mùi hương, cỏ hương bài và gỗ tuyết tùng đem lại một cảm giác ấm cúng, nhẹ nhàng, chững chạc hơn cùng một chút phấn tươi từ đóa diên vĩ tím khiến mùi hương trở nên nữ tính, nhẹ nhàng, thanh lịch và rất tinh tế.<br>Chance Eau Vive là một mùi hương được xếp vào nhóm hương Hoa – Gỗ - Xạ hương (Floral – Woody – Musk) chuẩn mực dành cho một quý cô và được thổi vào một làn hơi tươi trẻ với những note hương cam chanh ở đầu, khiến nó rất phù hợp với các chị em trẻ trung, năng động, có thể mặc đi học, đi làm, đi chơi cùng bạn bè, thâm chí có thể là những buổi hẹn hò thông thường.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('640b4cda-92be-4eb6-9b9f-50472e8bf2d3','Dolce & Gabbana Dolce Lily','27','nữ','Anh, Pháp, Đức',2022,'Quả chanh dây, Hoa lily, Xạ hương','Gợi cảm, Nữ tính, Thanh lịch','Hương đầu: Chanh Dây, Cam Bergamot, Chanh; Hương giữa: Hoa Lily, Hoa Hồng; Hương cuối: Xạ Hương, Gỗ Đàn Hương, Vanilla','Được ra đời vào năm 2022, Dolce Lily là phiên bản flanker mới nhất của Bộ Sưu Tập Dolce và là một bản nhạc được tấu lên nhằm tôn vinh sự tồn tại đầy quyến rũ của bông hoa Lily, loài hoa biểu trưng cho sự nữ tính và lòng nhân ái của phái đẹp.<br>Là một người phụ nữ hiện đại, mang trong mình nguồn năng lượng tươi mới, một khởi đầu mát mẻ của các tông hương Cam Chanh là một cách tinh tế để cùng nàng tạo ra sự tự tin, thoải mái toát ra trong bầu không khí xung quanh.<br>Cuối cùng, cô chưng cất một sự trầm ấm, nhịp nhàng. Thoải bước trên con phố với những sự tự tin, Xạ Hương xuất hiện nâng niu từng bước chân cô, Vanilla tạo ra những nét ấm áp, khơi gợi về một cô gái trẻ trung, luôn muốn tạo ra một sự cao đẹp nơi tâm hồn như những đóa hoa Lily nở rộ dưới ánh dương.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('6eb92726-2abe-4a00-a3a4-a1b03c1d6ebe','Dolce & Gabbana Dolce Rosa Excelsa EDP','27','nữ','Anh, Pháp, Đức',2016,'Hoa hồng, Hoa súng, Xạ hương','Nữ tính, Quyến rũ, Tinh tế','Hương đầu: Hoa cam, Hoa đu đủ; Hương giữa: Hoa hồng, Hoa hồng Turkish, Hoa súng, Hoa thuỷ tiên, Hoa loa kèn đỏ; Hương cuối: Xạ hương, Gỗ cashmere, Gỗ đàn hương','Như một cuộc dạo chơi trong khu vườn với những hoa là hoa, đó là gói gọn những gì mà Dolce & Gabbana Dolce Rosa Excelsa Eau de Parfum sắp thể hiện với bạn đó.<br>Câu hỏi đầu tiên đặt ra khi thử Dolce Rosa Excelsa EDP, chắc hẳn sẽ là \'Khu vườn này có những loại hoa gì thế?\', vì thoạt nhiên, bạn sẽ chẳng thể đoán được hương hoa nào là hương hoa nào. Ở đó hoà quyện sự thanh tươi, sắc cạnh tựa Cam chanh, với một chút ngọt đậm, mượt như Sữa, và cũng miên man hoài niệm với nét đẹp hơi \'vintage\' một chút.<br>Hương hoa ấy cứ mải miết đeo đuổi đến tận cuối cùng, không thiếu mà cũng không thêm thắt gì, cứ vần vũ ta trong khu vườn đầy mê hoặc, thần kỳ thuyết phục ta rằng chẳng cần phải chỉ mặt điểm tên cho rõ ràng mà vẫn nhận ra được nét đẹp của tổng hợp các loài hoa.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('6f009abe-b01b-4ca1-9a4c-e590d3bcd628','Gucci Flora Gorgeous Gardenia EDP','3','nữ','Anh, Đức, Pháp',2021,'Hoa lê, Đường nâu, Hoa nhài','Ngọt ngào, Gợi cảm, Mãnh liệt','Hương đầu: Hoa lê, Quả mọng đỏ, Quả quýt Ý; Hương giữa: Hoa dành dành, Hoa nhài, Hoa sứ (hoa đại); Hương cuối: Đường nâu, Hoắc hương','Gucci là một thương hiệu vốn rất thành công trong mảng nước hoa nữ, bằng những mùi hương khai thác nét đẹp mềm mại, nữ tính của các loại hoa và trái cây. Flora by Gucci cũng là một làn hương nữ tính dễ chịu và đáng yêu dành cho các quý cô, thế nhưng thường xuất hiện khá “le lói” trên thị trường dưới dạng những bản phát hành giới hạn theo từng năm hoặc sẽ dừng sản xuất sau vài năm phát hành trên thị trường. Phải đến năm 2021, Gucci mới cho ra một cái tên với ngoại hình cố định và mới mẻ cho dòng hương này, thay vì sử dụng những chiếc chai đựng được lấy cảm hứng từ kiểu dáng của Flora by Gucci năm 1966, ấy là Gucci Flora Gorgeous Gardenia Eau de Parfum.<br>Đựng trong một chiếc chai màu hồng với kiểu dáng như những chiếc lọ trên giá làm việc của một bác sĩ thảo mộc, Gucci Flora Gorgeous Gardenia thật sự sở hữu mùi hương cũng khá “gorgeous” như cái tên và ngoại hình. Với chủ điểm là hoa trắng, Dành dành và Nhài bung tỏa ngay từ những giây phút đầu tiên của mùi hương, được tăng thêm độ ngọt và mọng nước từ Quýt và Quả mọng. Một chút thanh ngọt nịnh mũi của Hoa lê, càng làm tăng thêm nét mịn màng trong từng làn hương hoa trắng trải ra khắp không gian.<br>Được làm ngọt từ Hoa và các thức Trái cây nịnh mũi, nên Gucci Flora Gorgeous Gardenia không phải là một thứ mùi hương ngọt lịm quá trớn, mà thanh thoát, uyển chuyển và đồng thời cũng sở hữu những rung động nữ tính ở mức tinh tế hơn. Khi khô xuống, Gucci Flora Gorgeous Gardenia vẫn tiếp tục duy trì được độ ngọt của mình bằng Đường nâu, nhưng chừng mực và vẫn giữ được khuôn mẫu sang trọng vốn có của mình.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('72e7936a-8e24-48c8-b200-44fd065d5e43','Giorgio Armani My Way','12','nữ','Pháp',2020,'Gỗ tuyết tùng, Hoa nhài, Hoa cam','Nữ tính, Tinh tế, Sang trọng','Hương đầu: Hoa cam, Cam bergamot; Hương giữa: Hoa huệ, Hoa nhài; Hương cuối: Xạ hương, Vanilla, Tuyết tùng','Nếu bạn đã trót lòng yêu thích Gucci Bloom trứ danh vì tông hương thanh tao, quyến luyến của Huệ và Nhài, thì có lẽ My Way Giorgio Armani sẽ đem đến cho bạn cảm giác còn hơn cả thoả mãn nữa đấy.<br>Mở ra con đường của mình không chút e ngại, My Way đúng như tinh thần phóng khoáng của mình đã bắt đầu với tông hương của Hoa cam quyện cùng chút thanh mát của Cam bergamot. Tất cả chỉ để dự báo cho sự xuất hiện đầy huy hoàng của Hoa huệ cùng Nhài khi tiến sâu hơn vào bóc tách từng lớp hương.<br>Thông thường, các nốt hoa trắng sẽ là ‘thủ lĩnh\' và chiếm trọn tất cả các spotlight trong một chai nước hoa, My Way cũng không phải ngoại lệ. Cho đến khi tất cả các nốt hương di chuyển đến con đường cuối cùng, khi có thêm sự xuất hiện của Vanilla. Vẻ ngọt ngào say đắm, bồng bềnh nhưng rất thực, lãng đãng xung quanh bầu không khí, khiến cho nét đẹp ban đầu hơi kiêu kỳ giờ đây trở nên gần gũi đến lạ.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('821716dc-9d21-413b-8347-25075415c02d','Dior J\'adore EDP','1','nữ','Pháp',1999,'Hương hoa cỏ trái cây','Gợi cảm, Sang trọng, Nữ tính','Hương đầu: Hoa mộc lan, Dưa gang, Quả đào, Quả lê, Cam Bergamot, Quả quýt hồng; Hương giữa: Hoa huệ trắng, Quả mận, Hoa tím, Hoa phong lan, Hoa lan Nam Phi, Hoa nhài, Hoa linh lan thung lũng, Hoa hồng; Hương cuối: Xạ hương, Hương Va ni, Gỗ tuyết tùng, Quả mâm xôi đen','Khi sử dụng nước hoa nữ Dior J\'adore EDP, sự nữ tính vô hạn của bạn như luôn chực chờ thời điểm bùng phát, hương thơm nước hoa lan tỏa mạnh mẽ, như mùi hương của bông hoa hồng tươi mát chớm nở trong ánh bình minh sớm mai.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('83debd66-113a-4b8c-b85e-ae37763894c6','Maison Francis Kurkdjian Oud Satin Mood','11','unisex','Pháp',2015,'Hương gỗ phương đông','Thanh Lịch, Tinh Tế, Độc Đáo','Hương chính: Hồng Bulgari, Hồng Thổ Nhĩ Kỳ, Vanilla, Gỗ trầm, Hoa violet, Benzoin','Hồng chưa bao giờ có thể lãng mạn hơn khi xuất hiện trong ấn phẩm Maison Francis Kurkjian Oud Satin Mood. Cá nhân tôi chỉ thích hoa trắng hoặc những nhóm Cam chanh tươi mát, thế nhưng Oud Satin Mood khiến tôi bất ngờ khi tạo hương vừa mạnh mẽ vừa dịu êm có thể thuyết phục một khứu giác kén chọn này.<br>Hồng trong Oud Satin Mood chững chạc và điềm đạm, không xô bồ và cũng chẳng \'đầy gai\'. Được phủ lên thêm hiệu ứng ấm áp, trầm lắng của Oud, giờ đây hợp hương này không đơn thuần chỉ quyến rũ ta mà còn ve vuốt, yêu chiều khứu giác của bất kỳ ai ngửi thấy được.<br>Tôi hay ví von cặp đôi Hồng & Oud có một hiệu ứng mềm mịn như nhung. Tấm vải nhung đỏ thẫm, mặn mà sắc sảo mà ta phải nâng niu rất cẩn thận. Kể cả khi bạn không thích Hồng và cũng chẳng chịu Oud, thì Maison Francis Kurkjian Oud Satin Mood vẫn sẽ có cách của riêng nó để khiến bạn phải để tâm tới mà thôi.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('924e87da-0b73-4a20-9cd8-d9086a9cf3f1','Le Labo Rose 31','22','unisex','Mỹ',2006,'Hoa hồng, Cỏ vetiver, Gỗ tuyết tùng','Cuốn hút, Tinh tế, Sang trọng','Hương đầu: Hoa hồng, Thì là (Ai Cập); Hương giữa: Hoa hồng, Cỏ hương bài, Gỗ tuyết tùng; Hương cuối: Xạ hương, Gỗ guaiac, Nhũ hương, Labdanum, Trầm hương','Khác với những mùi hương truyền thống vốn có, Le Labo Rose 31 đem lại sự quyến rũ vốn có từ những đặc trưng của Hoa hồng đến cho chủ nhân của mình thông qua những từng hương được trau chuốt tỉ mỉ.<br>Gom trọn mọi cảm xúc chỉ trong lần xịt đầu tiên, từng nốt hương ngọt nhẹ, ấm áp từ Cỏ hương bài và Gỗ tuyết tùng dìu dắt sự quyến rũ, thu hút của Hoa hồng lên trên bề mặt da thịt. Nằm trọn bên trên cơ thể, Hoa hồng bám lấy không dứt qua đến tầng hương giữa đến khi những nốt hương Thì là (Ai Cập) tạo ra một chuỗi liên tiếp những mùi hương phảng phất sự hấp dẫn, mềm mại đến lạ kì.<br>Sự trung lập của Le Labo Rose 31 ngày càng được khắc họa rõ hơn sau mỗi đợt hương Xạ phản ứng cùng Gỗ guaiac, Nhũ hương, Labdanum và Trầm hương. Đó là lí do tại sao Le Labo Rose 31 khi tiếp xúc trên cơ thế nam giới, hương thơm sẽ trở nên cá tính, quyến rũ còn lên da nữ thì lại hóa thành gợi cảm, dịu dàng.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('975824c7-651d-415f-8e4c-539add86ff46','Maison Francis Kurkdjian A La Rose','11','nữ','Pháp',2014,'Hoa hồng Bulgari, Cam bergamot Calabrian, Hoa violet, Gỗ tuyết tùng','Tinh tế, Nữ tính, Sang trọng','Hương đầu: Cam Bergamot (từ Calabria), Quả cam (từ California); Hương giữa: Hoa hồng Bulgaria, Hoa hồng Grasse (Pháp), Hoa Violet, Hoa mộc lan; Hương cuối: Xạ hương, Gỗ tuyết tùng','Hoa hồng là chủ đề muôn thuở trong thế giới nước hoa, từ những ngày đầu khởi nguồn của hương thơm cho tới ngày nay. Hồng có thể lộng lẫy, đỏng đảnh, choáng ngợp, rồi đôi khi lại e ấp, lấp ló trong màn sương sớm, bởi nó đa màu, đa sắc, giàu thái độ và đầy cảm xúc. Vì vậy, nếu bạn có hứng thú với loài hoa này, và theo đuổi phong cách thư thái nhẹ nhàng như những bông hoa trắng, thì Hoa hồng vẫn sẽ luôn có lựa chọn dành cho bạn, ấy là À La Rose của Maison Francis Kurkdjian.<br>Khoác Maison Francis Kurkdjian À La Rose lên mình, bạn hãy đơn giản tưởng tượng ra rằng mình đang mặc lên một tấm khăn, được dệt từ những cánh hoa hồng mềm mịn như nhung lụa. À La Rose mở ra bằng một bức tranh của vườn hồng sớm mai, tươi tắn, đẫm nước bằng cái thanh mọng của Bergamot, cùng chút ngọt ngào của Cam, tổng hòa ra một buổi sáng dễ chịu nơi vườn hồng mộng mơ. Hồng xuất hiện sớm, xuyên suốt từ đầu tới cuối của mùi hương, ẩm ướt, mềm mại, không đằm thắm và tình tứ như những thứ hoa hồng quen thuộc, cũng không mạnh mẽ bí ẩn như khi kết hợp với Trầm hương.<br>Maison Francis Kurkdjian À La Rose không phải là một thứ hoa hồng nổi bật, nồng nàn hay đánh cướp mọi sự thu hút khi xuất hiện, nhưng chắc chắn là một loài hoa hồng êm dịu, nịnh nọt khứu giác, để bất kỳ ai bắt qua làn hương cũng phải thích thú, quyến luyến.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('a3948660-682f-4529-9ddc-61fadbcf2f7a','Giorgio Armani Emporio Armani Stronger With You For Men','12','nam','Pháp',2017,'Hương vani, Bạch đậu khấu, Cây hạt dẻ','Nam tính, Tinh tế, Thu hút','Hương đầu: Bạch đậu khấu, Hồng tiêu, Lá hoa tím, Bạc hà; Hương giữa: Cây xô thơm, Dưa lưới, THơm, Hoa lavender, Quế; Hương cuối: Vani, Hạt dẻ nâu, Gỗ tuyết tùng, Nhựa cây Amberwood, Gỗ Guaiac','Hãng Giorgio Armani đã công bố một cặp đôi hoàn toàn mới trong bộ sưu tập nước hoa danh tiếng của hãng, và được ví von là “ Tình yêu hiện đại đích thực trong khướu giác”. Phiên bản nam giới với tên gọi Emporio Armani Stronger With you và phiên bản nữ là Because It’s You được ra mắt cùng lúc nào tháng 6 năm 2017. Emporio Armani Stronger With You được ra mắt trong sự kỳ vọng lớn của hãng Armani, dưới áp lực của những dòng nước hoa danh tiếng kinh điển của hãng như Gio Giorgio Armani hay Armani Code. Với tone mùi hương hoàn toàn khác biệt so với những dòng nước hoa đã từng phát hành của hãng, Chàng trai Emporio Armani sở hữu các tầng hương phức tạp, tạo ra những cảm xúc khó phán đoán. Điều bạn dễ dàng nhận thấy nhất khi lần đầu tiên tiếp xúc với chàng Emporio chính là sự ngọt ngào độc đáo, nhưng cực kỳ nam tính trong cách gợi ý sự chú ý từ đối phương.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('a7155acf-683f-4ec3-bed7-a72758d64c35','Bvlgari Splendida Rose Rose For Women EDP','15','nữ','Ý',2017,'Hoa hồng Đan Mạch, Quả mâm xôi, Xạ hương','Nhẹ nhàng, Nữ tính, Thanh lịch','Hương Đầu: Quả quýt hồng, Quả mâm xôi đen; Hương giữa: Hoa hồng Đan Mạch; Hương cuối: Cây hoắc hương, Gỗ đàn hương, Cỏ hương bài, Xạ hương','Được mệnh danh là bàn tay đầy ma thuật, Sophie Labbe - chủ nhân của nhiều bộ sưu tập nước hoa nổi tiếng cho không dưới 60 hãng thời trang nổi tiếng - đã cho ra đời Splendia Rose Rose Bvlgari vào năm 2017 như một lần nữa khẳng định tên tuổi của bà.<br> Như một bài ca Nữ quyền, Splendia Rose Rose toát lên vẻ kiêu kỳ, tự tin và đầy phóng khoáng tượng trưng cho phái nữ ở xã hội hiện đại ngày nay khi bắt đầu với tông hương thanh mát, tinh nghịch từ Cam quýt và Dâu đen mọng nước.<br>Ở tầng hương thứ hai, khi Sophie Labbe thể hiện cái tôi của bà bằng cách sử dụng độc một mùi hương - Hoa hồng - cũng chính là nhân vật chính tạo nên cái tên nước hoa này. Độc lập, quyến rũ với hương thơm kích thích đến lạ, Splendia Rose Rose là một vũ khí cho bất kỳ người phụ nữ nào sở hữu được nó.<br>Đến cuối ngày, cô nàng kiêu kỳ của chúng ta cũng để lộ ra một trái tim ấm áp, được hun nóng bằng Gỗ vetiver, Gỗ bạch đàn hương và không kém tinh tế với Xạ hương cộng hưởng cùng Hoắc hương.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('a8313137-116c-4449-aa30-01604789078e','Carolina Herrera Good Girl EDP','29','nữ','Tây Ban Nha',2016,'Đậu tonka, Ca cao, Hoa huệ, Hoa nhài','Quyến rũ, Nữ tính, Ngọt ngào','Hương đầu: Hạnh nhân, Cà phê, Cam Bergamot, Quả chanh vàng; Hương giữa: Hoa huệ, Hoa nhài Sambac, Hoa cam, Rễ Diên vĩ, Hoa hồng Bulgaria; Hương cuối: Đậu Tonka, Cacao, Vanilla, Kẹo Praline, Gỗ đàn hương, Xạ hương, Nhựa Hổ phách, Gỗ Cashmere, Quế, Hoắc hương, Tuyết tùng','Một sản phẩm không thể thiếu trên kệ tủ của bất kì cô gái sành điệu nào, Caroline Herrera Good Girl Eau de Parfum là một chiếc guốc sang trọng, biểu tượng của một quý cô ngọt ngào, thanh lịch và cũng rất mạnh mẽ.<br>Mùi hương của chai nước hoa được tạo nên bởi những điều tương phản tưởng chừng khó thể nào sánh đôi, nhưng chính những điều đó lại đem đến một sự hòa quyện hoàn hảo đến bất ngờ. Hãy tưởng tượng mà xem, Good Girl là tất thảy những sự ngọt ngào và êm dịu trên thế giới này được tổng hợp và chiết xuất lại. Tầng hương đầu tiên là mùi của Hạnh nhân ngọt bùi, cái mát mẻ của Cam Bergamot và Quả chanh vàng. Hương thơm tự nhiên, tao nhã đan xen mãnh liệt ngọt đắng tiến thẳng vào khứu giác, thúc tiến tinh thần ta và khơi gợi niềm cảm hứng cho một hành trình mới.<br>Tầng hương giữa lại đem đến một cảm giác ngọt ngào nhưng kiêu kỳ, toả sáng bởi sự kết hợp của những loài hoa khác nhau. Hương kem beo béo của Huệ hoà quyện với Hoa nhài Sambac tươi tắn, tất thảy làm nên hương thơm nữ tính nhưng không hề ủy mị, dịu dàng mà vẫn toát lên vẻ thanh lịch của Good Girl. Và rồi tầng hương cuối nào là Đậu Tonka, Vanilla hay kẹo Praline làm cho hương thơm béo ngậy, trầm ấm, có chút thoảng Hương Gỗ đầy lắng đọng, vấn vương.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('a94faa4d-7ffa-4802-8683-1dd22dcd6d9c','Jo Malone London English Pear & Freesia Cologne','10','nữ','Anh',2010,'Quả lê, Hoa diên vĩ, Hoa hồng, Xạ hương','Nhẹ nhàng, Sang trọng, Gợi cảm','Hương đầu: Quả lê, Quả dưa; Hương giữa: Hoa lan Nam Phi, Hoa hồng; Hương cuối: Xạ hương, Hoắc hương, Đại hoàng, Nhựa hổ phách','Hầu hết mọi người đều biết đến Jo Malone như một nhà hương Anh Quốc chuyên làm những mùi hương nhẹ nhàng, mơn man kiểu Eau de Cologne cổ điển, phải chứ? Jo Malone London English Pear & Freesia Cologne lại là sự khác biệt thú vị với phần còn lại, đôi khi mạnh mẽ lan tỏa, khi lại nhẹ nhàng mơn trớn đúng kiểu Jo Malone, một cách lạ kỳ.<br>Đã có lần, tôi mặc mùi hương này và đi chung thang với hai mẹ con cô bé nọ. Cô bé nhỏ ấy nói với mẹ rằng đang cảm thấy mùi hương hoa quả đang \'nổi dậy\'. Thú vị đấy bé con ạ, nhưng chẳng có thứ gì nổi dậy ở đây cả. Chúng chỉ đang thở, những nhịp thở lúc trầm lúc bổng của Quả lê mọng nước và chùm Lan Nam Phi ngọt ngào trong English Pear & Freesia. Hai thức ấy như quấn lấy nhau, dịu dàng tỏa hương trong một không gian nhẹ nhàng và vui tươi.<br>Đúng như cái tên, English Pear & Freesia Cologne là một màn trình diễn hoàn chỉnh của Lan Nam Phi và Quả lê, rồi đến khi khô xuống, Xạ hương dịu dàng xuất hiện, như cùng với hai nốt hương chính vỗ về làn da cùng khứu giác chúng ta cho tới lúc mùi hương biến mất.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('aa4c51f3-4c4b-4271-8cf7-ec2e8be8aad6','Louis Vuitton L’immensité','37','unisex','Pháp',2018,'Hương cay nồng phương đông','Nam tính, Nhẹ nhàng, Phóng khoáng','Hương đầu: Cam Bergamot, Gừng, Quả bưởi; Hương giữa: Cây hương thảo, Cây xô thơm, Hoa phong lữ, Hương nước; Hương cuối: Hổ phách, Hương Ambroxan, Hương Labdanum','Bậc thầy nước hoa Jacques Cavallier Belletrud đã kết tinh những trải nghiệm tuyệt vời của ông trong chuyến hành trình đến vùng biển mát lành, nơi khởi nguồn của chai nước hoa Louis Vuitton L’immensité. Là loại nước hoa đầu tiên trong 5 loại nước hoa Les Parfum Louis Vuitton dành cho nam đơn giản được ra mắt vào năm 2018. Tuy là thiết kế truyền thống nhưng thân chai thủy tinh chắc chắn, được gia công tỉ mỉ từng góc cạnh. Lớp trên cùng là nước thơm, trong vắt, chứa nhiều sương sớm, đã được kết tinh lại để tạo nên L’immensité hoàn hảo để hoàn thiện tinh chất.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('aa91bfaa-ef19-4bdc-afcb-46e71a7538ff','Dior Sauvage Parfum','1','nam','Pháp',2019,'Gỗ đàn hương, Olibanum, Cam bergamot','Lịch lãm, Nam tính, Lôi cuốn','Hương đầu: Cam Bergamot, Quýt; Hương giữa: Gỗ đàn hương; Hương cuối: Đậu tonka, Olibanum, Vani','Dior sauvage Parfum là phiên bản mới nhất trong bộ sưu tập nước hoa của nhà Dior trong dòng Sauvage, tiếp nối sự thành công của các phiên bản Sauvage EDT và Sauvage EDP. Một phiên bản mới được thiết kế đậm đà hơn nhưng vẫn giữ nguyên các ADN cốt lõi làm nên thương hiệu “Lady Killer” đình đám của Dior Sauvage. Chuyên gia Francois Demachy đã phát hành phiên bản Sauvage Parfume vào năm 2019, được lấy cảm hứng từ vùng thảo nguyên, thời điểm ánh trăng lên cao cùng bầu trời tối đen le lói ánh sáng của lửa trại.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('aede37ef-8b43-4dac-a267-2474b6c57297','Bvlgari Omnia Crystalline EDT','15','nữ','Ý',2005,'Hoa Cỏ Và Biển Cả','Bí ẩn, Gợi cảm, Tươi sáng','Hương đầu: Tre, Quả lê; Hương giữa: Hoa sen, Cây bã đậu, Trà; Hương cuối: Xạ hương, Rêu sồi, Gỗ Guaiac','Bvlgari Omnia Crystalline EDT mang lại cho người dùng một hương thơm tươi mát và nhẹ nhàng, đồng thời cũng thể hiện được sự cá tính với mùi hương đầu tiên đem lại cho bạn sự trẻ trung và nữ tính, với hương của trúc và lê mang đến cảm giác xanh ngắt, tươi mát. Tiếp đó, hương hoa sen dịu dàng và êm ái khiến nàng thư thái, dễ chịu. Hương giữa còn kết hợp với vị cay nồng ấm của cây bã đậu và sự tươi tắn của Cassia. Qua đó tạo nên nét nữ tính và mềm mại của Omnia Crystalline.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('afa559b3-1f65-44f4-b54b-b749c83b1073','Montblanc Legend Spirit Mini Size','17','nam','Tây Ban Nha',2016,'Hương nước, Hoa oải hương, Qủa bưởi, Cam bergamot','Tự tin, Nam tính, Hiện đại','Hương đầu: Cam Bergamot, Hồng tiêu, Quả bưởi; Hương giữa: Bạch đậu khấu, Hoa Lavender, Hương nước; Hương cuối: Xạ hương trắng, Hương gỗ trắng','Montblanc công bố Legend Spirit vào năm 2016 và là một phiên bản hoàn toàn mới so với bản gốc từ năm 2011, với khẩu hiệu \'Follow Your Spirit\'. Hương thơm thể hiện sự lịch lãm vượt thời gian, từ cổ điển cho tới hiện đại, nhưng vẫn giữ cốt cách nam tính đầy mạnh mẽ của cánh mày râu. Thành phần mùi hương mở đầu bằng sự pha trộn đầy tinh tế giữa Cam bergamot, Bưởi và Hồng tiêu, là mùi hương của sự tự tin và thành đạt. Midnote với sự có mặt của hoa Lavender cùng Bạch đậu khấu, hấp dẫn ánh mắt của mọi cô gái, cùng sự tươi mát của hương nước. Montblanc Legend Spirit là một người đang ông của tương lai dù đang sống ở hiện tại, bởi cách tiếp cận cùng phong cách rất cởi mở, thân thiện, hướng ngoại và chu đáo của mình, cũng chính vì vậy, Montblanc Legend Spirit cũng dễ dàng trở thành người chồng tương lai được chọn của các quý cô đến tuổi trưởng thành.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('b9be5c09-82b4-4de2-9320-ce302b93066b','new','30','nữ','Mỹ',2016,' Da lộn, Quả quýt hồng, Tiêu đen','Nữ tính, Tinh tế, Sang trọng','Hương đầu: Cam quýt, Tiêu đen; Hương giữa: Hoa hồng Bulgaria, Hoa hồng Grasse (Pháp), Hoa Violet, Hoa mộc lan; Hương cuối: Cỏ hương bài','aisja0q99 áoasasa','2026-01-17 03:54:09','2026-01-17 03:54:09',NULL),('ba564e45-56d6-4dd6-bc9d-2bbc0df39158','Thierry Mugler Alien','26','nữ','Pháp',2005,'Hoa nhài, Hổ phách, Gỗ','Bí ẩn, Quyến rũ, Nổi bật','Hương đầu: Hoa nhài.; Hương giữa: Hương gỗ.; Hương cuối: Nhựa hổ phách.','Thierry Mugler là một người có cá tính mạnh mẽ, thể hiện rõ qua tất cả những thứ ông tạo ra, từ những bộ trang phục ông đã từng thiết kế, hay những mùi hương khi chuyển sang tập trung vào Mugler Perfumes. Nước hoa của Mugler phần lớn đều được đón nhận nồng nhiệt từ người dùng, hoặc là những mùi hương được giới chuyên sâu đánh giá cao như dòng A*Men, Mirror Mirror hay đặc biệt là Les Exceptions, hoặc là thỏa mãn được nhu cầu của đại chúng và trở thành một “best-seller”. Alien là một cái tên thỏa mãn đại chúng như vậy, nổi tiếng và trở thành một di sản đặc trưng của Mugler.<br>Alien nối tiếp sự thành công của người chị Angel đi trước và đã duy trì được danh tiếng của Thierry Mugler trong ngành nước hoa, với một thủ pháp làm hương ngược lại hoàn toàn. Alien đánh vào sự đơn giản, không phải một mùi hương ngọt ngào đầy phức tạp như Angel, mà khai thác vẻ đẹp nữ tính gợi cảm của hương thơm chỉ trong hai nốt: Hoa nhài và Nhựa hổ phách, cùng một chút xíu gia giảm bằng hương Gỗ. Alien đại diện cho sự hỗn mang đúng với màu tím huyền diệu của chai nước hoa này, với mùi hương chuyển qua lại giữa các sắc thái cảm xúc. Khi thì tươi tắn mềm mại với Nhài, khi lại gợi cảm, quyến rũ và tối màu hơn với Nhựa hương, lúc lại lơ lửng ở giữa, tạo ra cảm xúc thú vị cho người thưởng thức. Một mùi hương không phức tạp, nhưng có thái độ, ở giữa và biến chuyển qua lại, vừa ngây thơ hiền dịu mà lại rất “đàn bà”.<br>Alien thực tế không dành cho số đông, và ai yêu thích nó thường đều đã xây dựng được những cá tính riêng về việc chọn mùi hương cho bản thân. Alien đủ đằm thắm, cũng chẳng thiếu nồng nhiệt, mạnh mẽ bung tỏa trên làn da.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('bcbd3d44-e5b4-4c94-ac9f-3a15b62667db','Jean Paul Gaultier Scandal','24','nam','Pháp, Tây Ban Nha',2023,'Hương Hoa Oải Hương, Hương Vanilla, Đậu Tonka, Mật Ong','Ngọt ngào, Nam tính, Cuốn hút','Hương Đầu: Oải hương, Bạc hà; Hương Giữa: Vanilla, Benzoin; Hương Cuối: Mật ong, Đậu tonka, Thuốc lá','Nếu bạn là nam và yêu thích những nét hương ngọt ngào, đậm nét, thì ấn phẩm mới đến từ nhà Jean Paul Gaultier - Le Male Elixir chắc chắn sẽ khiến bạn phải xiêu lòng đấy!<br>Vị ngọt làm nên tính cách của Jean Paul Gaultier Le Male Elixir đến từ Vanilla và Mật ong. Vanilla bông phấn mịn màng, quyện cùng Mật ong sánh đặc, tạo nên tông vị mềm mại nhưng vẫn da diết vô cùng. Thuốc lá đến ngay sau đó như khẳng định sự nam tính vẫn ở đó xuyên suốt hành trình mùi hương.<br>Dù \'ngọt\' là tính từ chính để miêu tả Jean Paul Gaultier Le Male Elixir, thế nhưng ấn nấp trong các tầng hương còn có cả Bạc hà the lạnh, Oải hương đậm đà hương thảo mộc, và cả Đậu tonka khô hăng, ấm áp nữa.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('c877dafd-727d-41a8-a0ea-e2a8c4e866a9','Yves Saint Laurent Libre EDT','6','nữ','Pháp',2021,'Trà lài, Hoa cam, Hoa nhài','Tưới mới, Tự do, Quyến rũ','Hương đầu: Oải Hương, Cam Bergamot, Quả Quýt; Hương giữa: Trà Nhài, Hoa Cam, Hoa Nhài; Hương cuối: Xạ Hương, Long Diên Hương, Vanilla.','Libre (2019 - EDP) là một mùi hương thành công của YSL khi được đón nhận nồng nhiệt từ cả người dùng và những chuyên gia, với việc ẵm rất nhiều giải thưởng được bình chọn bởi người tiêu dùng, các tổ chức uy tín (Trong đó có cả FiFi). Tiếp nối sự thành công đó Yves Saint Laurent quyết định cho ra mắt thêm flankers cho dòng nước hoa này vào 2020 và 2021, đó là phiên bản Libre Intense (2020) và Libre Eau de Toilette (2021).<br>Đúng với tinh thần EDT, Libre EDT vẫn khai thác mạnh mẽ vào một mùi Oải hương nhiều phấn rất nữ tính và được chị em yêu thích từ Libre, cùng hương hoa Cam và Nhài ngọt dịu tôn thêm lên cái sự nữ tính ấy,  tươi và dịu hơn với hương thơm thanh khiết của Trà. Trà Nhài, pha thêm một chút hoa Cam, và nhiều phấn, vẫn giữ cái tinh thần “nữ quyền” mạnh mẽ ở phiên bản gốc nhưng đã phần nào đó thanh khiết và lả lướt hơn.<br>Về cuối, khác với Libre Intense khi cường điệu note hương ngọt ngào của Vanilla bằng Coumarin (Đậu tonka), Libre EDT lại bớt ngọt hơn, phấn hơn 1 chút và thanh lịch hơn. Điều này chắc chắn sẽ làm cho Libre EDT bớt “sexy” hơn trong mắt các chị em hảo ngọt, nhưng lại khiến mùi hương này trở nên nhẹ nhàng và đa dụng hơn. ','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('d42c20c2-448a-4f42-b89b-afe2c99f77bd','Chanel Allure Homme EDT','2','nam','Pháp',1999,'Hương vani, Quả chanh vàng','Tinh tế, Quyến rũ, Lãng mạn','Hương đầu: Chanh, Đào, Gừng, Quýt, Hoa Oải Hương, Cam Bergamot; Hương giữa: Tiêu, Hoắc Hương, Tuyết Tùng, Cỏ hương Bài, Hoa Hồng, Hoa Nhài, Gỗ Hồng Mộc Brazil, Hoa Dành Dành, Hoa Lan Nam Phi, Tiêu Hồi Cần; Hương cuối: Vani, Đậu Tonka, Dừa, Gỗ Đàn Hương, Hổ Phách, Benzoin, Da Thuộc, Xạ Hương, Rêu Sồi','Sự quyến rũ hay tốc độ của anh ấy rất quyết đoán, nhưng lại pha chút nhẹ nhàng. Thành phần được tạo ra từ bốn dòng hương chính: sự tươi mát của màu xanh lá cây, sự sắc nét ấm áp của hạt tiêu, sức mạnh và sự sang trọng của gỗ, và sự gợi cảm ấm áp của Benzoin và tonka.<br>Không có đường nét chính nào có thể được cảm nhận một cách riêng biệt, chúng cùng nhau tạo nên một tổng thể hài hòa. Bằng cách kết hợp những thành phần phức tạp, tạo nên một Chanel Allure Homme Eau de Toilette đã ghi dấu ấn vượt thời gian trong hơn 2 thập kỷ qua.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('d851be84-b9a3-40ed-88d9-73d9d4d958df','Diptyque Eau Rose','20','nữ','Pháp',2012,'Hoa hồng, Quả vải, Quả lý chua đen','Sang trọng, Gợi cảm, Ấm áp','Hương đầu: Cam Bergamot, Quả lý chua đen, Quả vải; Hương giữa: Hoa nhài, Hoa phong lữ, Hoa hồng; Hương cuối: Xạ hương, Gỗ tuyết tùng, Mật ong trắng','Đem tới những hương thơm dành tặng riêng cho những nữ hoàng xinh đẹp, quyến rũ. Diptyque Eau Rose như một bóng hồng dịu dàng luôn tồn tại đặc biệt bên trong các quý cô điệu đà, sang chảnh.<br>Được ra mắt vào năm 2012, Diptyque Eau Rose chẳng cần thể hiện ra bên ngoài cũng dễ dàng nhận được cái gật đầu đồng ý cùng danh hiệu nữ hoàng của những loài hoa. Vốn dĩ chai Eau Rose có được danh hiệu quyền quý này bởi vì hương Hoa hồng quyến rũ được lấy làm chủ đạo và phảng phất mạnh mẽ thu hút lấy những ánh nhìn khao khát dù cho là nam giới hay nữ giới.<br>Không vội vàng trao mình trong những giây phút ban đầu, những tinh chất Cam bergamot, Quả lý chua đen và Quả vải thay nhau lần lượt gọi mời, quấn quýt nơi đầu mũi tạo ra những cảm giác dễ chịu giúp rũ bỏ đi những mệt mỏi, căng thẳng mà sẵn sàng đón nhận những cảm xúc tuyệt vời hơn cùng Eau Rose.<br>Tạo thành từng đợt dồn dập và mạnh liệt, Eau Rose thực sự khiến cho người khác phải trầm trồ và trở nên điên loạn trước vẻ quyến rũ khó cưỡng của những nốt hương Hoa hồng, Hoa nhài và Hoa phong lữ. Không chỉ mang lại những hương thơm ngọt dịu đặc trưng, từng nốt hương như gợi lên sự khoái cảm bên trong lắp đầy trong tâm trí người xung quanh cùng những câu hỏi “Là ai?” – “Hương thơm này đến từ đâu?” – “Có phải từ cô gái vừa lướt qua ư?”.<br>Để lại sự quyến rũ của mình qua những nơi mình lướt qua, Eau Rose còn vô tình lưu lại những mùi hương của mình bằng những note hương Xạ quen thuộc hợp cùng nền Gỗ tuyết tùng để tôn lên nét lắng đọng đầy ngọt ngào của Mật ong trắng. Diptyque không chỉ gợi nhắc đến hình dáng của một quý cô giàu sang, thơm tho mà còn đem tới sự quyến rũ, gợi cảm khiến cho các chàng trai phải thèm khát đến tột cùng.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('d880d78f-a7ce-4bc5-9afb-3550c5ea29a0','Valentino Donna Born In Roma Green Stravaganza','18','nữ','Pháp',2024,'Hương Trà Đen Lapsang Souchong, Hoa Nhài, Vanila','Ngọt Ngào, Tươi Mới, Quyến Rũ','Hương đầu: Trà Chánh san tiểu chủng (Lapsang Souchong Tea); Hương giữa: Hoa Nhài; Hương cuối: Vanilla','Ra mắt vào năm 2024, Valentino Donna Born in Roma Green Stravaganza là lời thì thầm đầy sức sống đến từ kinh đô hoa lệ, nơi những khu vườn thanh mát của Rome được tái hiện qua từng tầng hương. Với thiết kế chai màu xanh lục bắt mắt, cùng họa tiết Rockstud đặc trưng, đây không chỉ là một chai nước hoa, mà là một tuyên ngôn phong cách cho người phụ nữ hiện đại, biết tận hưởng cuộc sống theo cách riêng.<br>Mùi hương mở đầu bằng trà Lapsang Souchong, nhẹ nhàng, có chút khói quyện đầy thư giãn, như một buổi chiều thảnh thơi giữa khu vườn xanh. Khi hương trà dần dịu xuống, hoa nhài bắt đầu nở rộ mềm mại, trong trẻo và nữ tính đến khó quên. Cuối cùng, tất cả được ôm ấp trong lớp nền vanilla ấm ngọt, dịu dàng lưu lại trên da như dư âm của một ánh nhìn tinh tế.<br>Donna Green Stravaganza là lựa chọn lý tưởng cho những nàng yêu nét đẹp tự nhiên, không gồng gánh chỉ cần một lớp hương nhẹ đủ khiến người khác ngoái nhìn. Phù hợp cho cả ban ngày lẫn buổi tối, đặc biệt là những dịp bạn muốn mang theo mình một chút tự do, thanh mát và nữ tính có chiều sâu.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('d9badc88-387c-472d-84a0-f4d948d19cbc','Prada Luna Rossa Sport EDT','16','nam','Anh, Pháp',2015,'Hoa oải hương, Hương vanila, Đậu tonka','Nổi bật, Hấp dẫn, Hiện đại','Hương đầu: Quả bách xù, Gừng; Hương giữa: Oải hương; Hương cuối: Vanilla, Đậu Tonka','Có vẻ như trong những mùi hương đến từ dòng Luna Rossa của Prada, thì Sport là một cái tên khác biệt nhất so với những người anh em đồng trang lứa, và cũng là một nhân vật “thiếu” DNA Prada nhất trong kho nước hoa của nhà mốt đến từ Ý.<br>Prada Luna Rossa Sport Eau de Toilette không khai thác mùi hương từ những nốt quen thuộc với fan của Prada, là Diên vĩ, Phấn hay Hổ phách, cũng không phải là đất diễn của các nốt hương tổng hợp đại diện cho một xu hướng mùi hương hiện đại như những người anh em Luna Rossa. Khởi đầu với Bách xù và Gừng, những nốt hương quen thuộc với người yêu nước hoa cổ điển, mở ra một chút tươi thanh lịch, gọn gàng và sạch sẽ. Oải hương vẫn nắm giữ vị trí trung tâm trong Luna Rossa Sport, gia tăng màu sắc thanh lịch cổ điển trong mùi hương, với một thái độ nhã nhặn nền nã. Cùng với Oải hương, mùi hương này đem tới một vị ngọt dịu, hơi ngậy và mềm mại, đem lại cảm giác mãnh liệt hơn để đúng với cái tên Sport, được tạo thành bởi Vanilla và Đậu Tonka.<br>Thật khó hiểu khi với mùi hương này, Prada lại đặt cho nó một cái tên là Sport. Nhưng Luna Rossa Sport là một chai nước hoa dễ chịu, nịnh mũi và có thể đáp ứng bất kỳ yêu cầu nào đến từ các quý ông. Đó là sự ngọt ngào, dễ mến và nét thanh lịch chỉn chu.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('dedd73bf-1ef5-4a63-9078-b879a5bb1a01','Burberry Hero','5','nam','Anh',2021,'Gỗ tuyết tùng, Cây bách xù, Cam bergamot','Nam tính, Mạnh mẽ, Tự do','Hương đầu: Cam Bergamot; Hương giữa: Quả Bách Xù, Tiêu Đen; Hương cuối: Tuyết Tùng Atlas, Tuyết Tùng Virginia, Tuyết Tùng Himalaya','Thương hiệu Burberry cho ra mắt dòng nước hoa mới mang tên Hero vào năm 2021 với nhiều hứa hẹn đây sẽ là một trong những chai nước hoa vô cùng được yêu thích bởi cánh mày râu.<br>Burberry Hero mở ra với tông mùi tươi mát của cam Bergamot, mang lại cảm giác tràn đầy sức sống của những ngày đầu xuân và có đôi chút lành lạnh trong những cơn gió của thành phố London. Hương xanh ấy sẽ được cộng hưởng thêm với những quả Bách Xù mọng nước. Xanh và tươi nhưng vẫn không thể thiếu đi được những nét nam tính mạnh mẽ nhờ có Tiêu đen. Hương cay này là một trong những nét hương nổi bật và đặc trưng có trong mỗi dòng nước hoa của thương hiệu Burberry.<br>Ngôi sao chính của Burberry Hero không phải ở tầng hương giữa mà la ở tầng hương cuối. Tổ hợp gỗ Tuyết Tùng đến từ nhiều địa danh nổi tiếng như Virginia, đỉnh Atlas và đỉnh Himalaya, nâng cấp độ nam tính, mạnh mẽ của mùi hương lên gấp bội. Burberry Hero chắc chắn sẽ thể hiện bản lĩnh của một người đàn ông dám nghĩ dám làm, sống đúng với bản chất và màu sắc riêng của chính mình.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('e0eae91c-82ce-4f6b-a2a0-c04db406dcb1','Prada Luna Rossa Carbon','16','nam','Anh, Pháp',2017,'Hương Ambroxan, Hoa lavender, Hương kim loại','Lịch lãm, Nam tính, Cuốn hút','Hương đầu: Cam Bergamot, Tiêu; Hương giữa: Hoa Oải Hương, Cồn đất cát, Hương của nước, Hương kim loại, Than đá; Hương cuối: Cây hoắc hương, Hương Ambroxan','Prada Luna Rossa Carbon được ra mắt vào năm 2017 dưới sự sáng tạo của chuyên gia nước hoa Daniela Andrier. Một đứa con xuất sắc trong đại gia đình Luna Rossa của Prada với triết lý thiết kế mùi hương đầy nam tính dựa theo nhóm hương kinh điển Ambroxan và Hoa lavender. Hẳn đã rất nhiều người mê mẩn và đắm chìm trong các note hương Ambroxan hay Lavender trong Dior Sauvage hay Versace Eros, hai chai nước hoa làm mưa làm gió và đại diện cho sự quyến rũ một cách đầy nam tính của hai thương hiệu hàng đầu.<br> Nhiều sự so sánh về các tầng hương của Prada Luna Rossa Carbon dành cho hai nhân vật kia, về cảm giác, về các note hương hay về cảm xúc mang lại. Bản thân Prada Luna Rossa Carbon mang trong mình sự quyến rũ đầy khiêu khích của Dior Sauvage EDT ngay cú xịt đầu tiên, đó là khi Lavender và Ambroxan hoạt động hết công suốt, tạo ra sự mạnh mẽ một cách tuyệt đối, thì sự tham gia của cam bergamot lại làm tươi mát cùng sự tròn vị của tiêu đen khiến cái gắt ở tầng hương đầu của Prada Luna Rossa Carbon giảm đi đáng kể. Việc có thêm than đá, đúng như cái tên hãng đặt, Carbon chính là sự khác biệt ở chàng trai hấp dẫn này, nó khiến anh chàng này định hình được phóng cách của mình, sự mạnh mẽ cuốn hút nhưng rất lạnh lùng.<br>Vị ngọt nhẹ và đầy sức hút của lavender ở base note kết hợp cùng hương nước lại khiến bản thân nhiều người so sánh với gã thần tình yêu Versace Eros, điều này chỉ duy trì trong khoảng thời gian ngắn khi Prada Luna Rossa Carbon xuống da sau 20 phút mà thôi. Nếu bạn hỏi tôi Prada Luna Rossa Carbon phù hợp vào thời gian nào và phù hợp với đối tượng nào, thì với khía cạnh cá nhân, gã này phù hợp cho mọi không gian và thời gian, sự cân bằng giữa vị ngọt và thanh tươi ở Prada Luna Rossa Carbon là điều khiến gã này trở nên hoàn hảo. Và với những người đàn ông trẻ trung nhưng lại trưởng thành, hiện đại, thì Prada Luna Rossa Carbon là thứ không nên thiếu trọng bộ sưu tập của chính mình.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('e4a87b9b-8655-4736-bc3c-1c64564a5878','Versace Eros For Men','4','nam','Ý',2012,'Hương thơm dương xỉ','Nam tính, Gợi cảm, Thu hút','Hương đầu: Cây bạc hà, Táo xanh, Quả chanh vàng; Hương giữa: Đậu Tonka, Hoa phong lữ, Hương Ambroxan; Hương cuối: Hương Va ni Madagascar, Cỏ hương bài, Rêu sồi, Gỗ tuyết tùng Virginia 2, Gỗ tuyết tùng Atlas','Nước hoa nam quyến rũ Versace Eros For Men EDT là mùi hương phù hợp với bất kỳ người đàn ông nào, nhưng với Parfumerie nó phù hợp hơn với những người đàn ông trưởng thành đầy bản lĩnh, cầm lên được thì bỏ xuống được, thôi thúc họ thể hiện được cái tôi một cách thông minh.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('e972c680-1b37-41b2-803d-de5294e518df','Tom Ford Ombre Leather Parfum','8','unisex','Mỹ, Thuỵ Sĩ',2021,'Da thuộc, Lá hoa violet, Hoa nhài Sambac','Sang trọng, Thanh lịch, Quyến rũ, Gây nghiện','Hương đầu: Lá Violet và Tuyết Tùng; Hương giữa: Hoa Nhài Sambac và Orris;  Hương cuối: Da Thuộc, Hương Gỗ và Thuốc Lá.','Sự xuất hiện của siêu phẩm Tom Ford Ombre Leather vào năm 2018 đã tạo ra một làn sóng dữ dội bởi mùi hương Da Thuộc chủ đạo vô cùng nam tính.<br>Sau 3 năm, tức là năm 2021, một phiên bản mới nhất được ra mắt - Tom Ford Ombre Leather Parfum cùng những hình thái mới của một gã đàn ông được mô phỏng từ một khía cạnh khác biệt và vô cùng đặc biệt.<br>Tầng hương đầu xuất hiện cùng với mùi hương Gỗ Tuyết Tùng và Lá Violet đã mang đến một hỗn hợp cân bằng đầy tinh tế, mùi hương thanh ngọt hòa cùng hương trầm ấm của gỗ là một điều vô cùng táo bạo để mang lại một sự khác biệt đầy cá tính.<br>Phía tầng hương sau là sự xuất hiện của Hoa Nhài Sambac, có lẽ ở phiên bản Parfum dù được nâng cấp ở phần nồng độ tinh dầu để mùi hương trở nên mạnh mẽ hơn thì phần xuất hiện của Hoa Nhài Sambac lại đi ngược lại hoàn toàn với định hướng mùi hương của Ombre Leather, phần hoa Nhài có phần dày mùi hương thanh tươi hơn như 1 cách để nhìn vào gã đàn ông bụi bặm phong trần kia bằng một khía cạnh sâu sắc hơn với tâm hồn cũng yếu đuối cũng muốn được đồng cảm.<br>Ombre Leather Parfum là nguồn cảm hứng bất tận đến từ khu vực miền Tây Nước Mỹ, nơi mà sự bụi bặm và phong trần của những gã cao bồi với chiếc áo da đang trầm ngâm với những điếu thuốc dang dở.<br>Mùi hương của Da Thuộc được khai thác rõ rệt và mạnh mẽ hơn để tạo ra những dấu ấn đúng tinh thần như cái tên đã được sinh ra - Ombre Leather Parfum. Ngoài ra, sự kết hợp với thuốc lá đã thực sự khiến Ombre Leather một lần nữa lại ghi dấu ấn trong lòng giới mộ điệu mùi hương.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('ed46877a-20ab-4e7d-a570-0436b32cd117','Jean Paul Gaultier Le Male Elixir','24','nam','Pháp, Tây Ban Nha',2023,'Hương Hoa Oải Hương, Hương Vanilla, Đậu Tonka, Mật Ong','Ngọt ngào, Nam tính, Cuốn hút','Hương Đầu: Oải hương, Bạc hà; Hương Giữa: Vanilla, Benzoin; Hương Cuối: Mật ong, Đậu tonka, Thuốc lá','Nếu bạn là nam và yêu thích những nét hương ngọt ngào, đậm nét, thì ấn phẩm mới đến từ nhà Jean Paul Gaultier - Le Male Elixir chắc chắn sẽ khiến bạn phải xiêu lòng đấy!<br>Vị ngọt làm nên tính cách của Jean Paul Gaultier Le Male Elixir đến từ Vanilla và Mật ong. Vanilla bông phấn mịn màng, quyện cùng Mật ong sánh đặc, tạo nên tông vị mềm mại nhưng vẫn da diết vô cùng. Thuốc lá đến ngay sau đó như khẳng định sự nam tính vẫn ở đó xuyên suốt hành trình mùi hương.<br>Dù \'ngọt\' là tính từ chính để miêu tả Jean Paul Gaultier Le Male Elixir, thế nhưng ấn nấp trong các tầng hương còn có cả Bạc hà the lạnh, Oải hương đậm đà hương thảo mộc, và cả Đậu tonka khô hăng, ấm áp nữa.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('f34bd5af-95a5-4926-bf3b-a89b5d2f1245','Salvatore Ferragamo Savane di Seta','28','unisex','Ý',2021,'Bơ diên vĩ, Gỗ đàn hương, Hạt cà rốt','Cuốn hút, Nổi bật, Tinh tế','Hương đầu: Hạt cà rốt; Hương giữa: Rễ cây diên vĩ; Hương giữa: Gỗ đàn hương','Có bao giờ bạn bắt gặp một vẻ đẹp bất bình thường vì quá đơn giản chưa? Tối giản có thể là một xu hướng, nhưng Savane di Seta còn bình dị hơn cả tối giản nữa. Tất nhiên, nói thế không có nghĩa mùi hương này được tạo nên xuề xoà hay không công kỹ, chỉ là vẻ đẹp này quá lạ lẫm so với hằng hà sa số những “bình hoa di động” trên thị trường hiện nay.<br>Không có lấy một nốt hương Hoa hay Trái cây, nhưng Savane di Seta có thể mau chóng khiến ta thấy dễ chịu, được ve vuốt với hương vị bồng bềnh, hơi phấn của Rễ cây diên vĩ. Nét hương phấn này của Rễ cây diên vĩ không quá nữ tính, hơi ướm một chút đất và có những nét màu tối nếu ngửi kỹ.<br>Để làm dày thêm và tạo chiều sâu cho tổng thể mùi hương, Savane di Seta đã chỉ sử dụng đúng duy nhất mùi hương của Gỗ đàn hương với tông vị ấm áp, ngọt đậm đặc trưng. Thế đấy, chỉ với vỏn vẹn những nốt hương này thôi, đơn giản quá sức tưởng tượng, nhưng ấn tượng mà bạn sẽ có với Savane di Seta không hề đơn giản như vậy đâu.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('f5c48d75-a24c-4b55-a283-37c4c884f79b','Chanel Bleu de Chanel EDT','2','nam','Pháp',2010,'Bưởi, Hương nhang, Gừng, Chang vàng','Sang trọng, Gợi cảm, Lịch lãm','Hương đầu: Quả bưởi, Quả chanh vàng, Bạc hà, Tiêu hồng; Hương giữa: Gừng, Nhục đậu khấu, Hoa nhài, Iso E Super; Hương cuối: Nhang, Cỏ hương bài, Gỗ tuyết tùng, Gỗ đàn hương, Hoắc hương, Nhựa hương Labdanum, Xạ hương trắng','Chanel Bleu de Chanel đã đem tới thế giới hương thơm một mùi hương dễ chịu. Cam chanh mở màn bằng nét đặc trưng của nốt hương Bưởi, tươi sáng mọng nước cùng Gừng thanh lịch sạch sẽ, rồi nhẹ nhàng thoang thoảng chút hương hoa. Gừng của Bleu de Chanel rõ ràng, dễ gần, đẹp và nịnh mũi. Lắng dần xuống, mùi hương của Bleu de Chanel trở nên dày và có chiều sâu hơn với Nhang mềm ngọt, cùng sự rắn chắc vững chãi của hương Gỗ, qua hương thơm từ Cỏ hương bài, Gỗ tuyết tùng và Đàn hương.<br>Bạn thấy chứ? Không cần bàn quá nhiều về mùi hương của Bleu de Chanel, một hương thơm dễ mến và đa dụng. Sự thành công của Bleu de Chanel thậm chí còn lớn đến mức tạo thành một trào lưu những mùi hương đi theo phong cách của chai nước hoa này. Tươi sáng, dễ chịu ở giai đoạn mở đầu, và tối dần về hậu hương với các nốt hương có chiều sâu như Gỗ, Hoắc hương hay Nhang, có thể tùy biến nhưng vẫn phải tuân theo một tôn chỉ tuyệt đối. Ấy là dễ mến, dễ dùng và phù hợp với mọi dịp bạn cần, còn được gọi là các “blue fragrances”.<br>Liệu Bleu de Chanel còn được các quý ông yêu thích và sử dụng đến khi nào, chẳng ai có thể biết trước được. Thế nhưng với tuổi đời đã hơn 10 năm trên thị trường, Bleu de Chanel vẫn chưa một lần rời khỏi top những mùi hương được yêu thích và bán chạy nhất, thành tích đó là đủ để chứng minh chất lượng tuyệt đối của cái tên này.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('fac7c76d-c86e-4f9e-8bec-472060ebd642','Prada Paradoxe Virtual Flower','16','nữ','Pháp',2024,'Hương Hoa Nhài, Hoa Cam Đắng, Cam Bergamot','Nhẹ Nhàng, Tươi Mát, Cuốn Hút','Hương đầu: Cam Bergamot; Hương giữa: Hoa nhài, Hoa cam; Hương cuối: Xạ hương, Hạt vông vang (Ambrette)','Khi hương hoa trắng chạm đến thế giới mộng ảo<br>Ra mắt năm 2024, Paradoxe Virtual Flower là chương tiếp theo đầy mới mẻ của nhà mốt Prada trong bộ sưu tập Paradoxe, nơi vẻ đẹp nữ tính được tái hiện qua lăng kính hiện đại cùng sự tươi trẻ giàu năng lượng. Mùi hương này như một đoá hoa trắng bước ra từ giấc mơ, nhẹ nhàng nhưng vẫn đầy ấn tượng, như một lựa chọn đẹp của những cô nàng yêu sự tinh tế mà chẳng ngại khác biệt.<br>Mở đầu là Cam Bergamot từ Calabria, một khởi đầu mát lành, sáng bừng và mang lại cảm giác như làn gió đầu ngày lướt qua làn da. Sự tươi mát ấy là tấm nền tuyệt đẹp dẫn tới sự bung nở của Nhài và Hoa cam: nữ tính, mềm mại và thoảng chút ngọt, như một nụ cười nhẹ luôn khắc dấu trong tim nếu lỡ lọt tầm mắt. Sự nữ tính đẹp đẽ ấy lan tỏa trên lớp nền gợi cảm trong trẻo được thiết lập bởi Xạ hương trắng và Hạt vông vang (Một loại \'xạ hương\' thực vật), để viết lại một điểm kết cho Paradoxe Virtual Flower bằng sự ấm áp, như mùi da sạch thoảng hương hoa, lưu luyến và đầy cảm xúc.<br>Virtual Flower là lựa chọn lý tưởng cho những ngày bạn muốn bản thân trở nên nhẹ tênh, tự do nhưng vẫn có điểm nhấn rất riêng. Thích hợp với mùa xuân - hè, cả ban ngày lẫn buổi tối, như là một hương thơm đặc trưng ấn tượng mà không phô trương, và luôn khiến người khác muốn lại gần thêm chút nữa.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL),('ffb4612d-fc17-45d5-a0e7-699001217efe','Louis Vuitton Apogée EDP','37','nữ','Pháp',2016,'Hương hoa cỏ trái cây','Ngọt ngào, Tinh tế, Nữ tính','Hương đầu: Trái cam, Trái cam Tangerine; Hương giữa: Hoa mộc lan, Hoa nhài, Hoa hồng, Hoa linh lan thung lũng; Hương cuối: Gỗ Guaiac, Gỗ đàn hương, Xạ hương trắng','Nước hoa nữ LV Apogée được đánh giá là một trong 3 mùi bán chạy nhất trong bộ sưu tập mới nhất Les Parfums của thương hiệu Louis Vuitton, hương thơm mở ra những khía cạnh nữ tính, thuần khiết và tinh tế hơn trong nét đẹp của phụ nữ.','2025-12-30 16:05:33','2025-12-30 16:05:33',NULL);
